-- ───────────── 집계 컬럼을 실제 행 수로 맞춘다 ─────────────
UPDATE listings l SET wish_count = (SELECT COUNT(*) FROM wishes w WHERE w.listing_id = l.id);
UPDATE comments c SET like_count = (SELECT COUNT(*) FROM comment_likes k WHERE k.comment_id = c.id);
UPDATE posts p SET
  comment_count = (SELECT COUNT(*) FROM comments c WHERE c.post_id = p.id AND c.deleted_at IS NULL),
  reaction_count = (SELECT COUNT(*) FROM post_reactions r WHERE r.post_id = p.id);
UPDATE post_poll_options o SET vote_count = (SELECT COUNT(*) FROM post_poll_votes v WHERE v.option_id = o.id);
-- 집계 갱신이 updated_at을 바꾸지 않도록 작성 시각으로 되돌린다
UPDATE posts SET updated_at = COALESCE(edited_at, created_at);
UPDATE comments SET updated_at = created_at;
